class HotelSummary {
  const HotelSummary({required this.id,required this.name,required this.address,required this.city,required this.latitude,required this.longitude,required this.rating,required this.mainImageUrl,required this.startingRate,required this.availableRooms,required this.transportAvailable,this.approvalStatus,this.rejectionReason});
  final String id,name,address,city,mainImageUrl; final double latitude,longitude,rating,startingRate; final int availableRooms; final bool transportAvailable; final String? approvalStatus,rejectionReason;
  factory HotelSummary.fromJson(Map<String,dynamic> j)=>HotelSummary(id:'${j['id']}',name:'${j['name']??''}',address:'${j['address']??''}',city:'${j['city']??''}',latitude:(j['latitude'] as num?)?.toDouble()??0,longitude:(j['longitude'] as num?)?.toDouble()??0,rating:(j['rating'] as num?)?.toDouble()??0,mainImageUrl:'${j['mainImageUrl']??''}',startingRate:(j['startingRate'] as num?)?.toDouble()??0,availableRooms:(j['availableRooms'] as num?)?.toInt()??0,transportAvailable:j['transportAvailable']==true,approvalStatus:j['approvalStatus']?.toString(),rejectionReason:j['rejectionReason']?.toString());
}
class HotelRoom {const HotelRoom({required this.id,required this.roomType,required this.capacity,required this.availableRooms,required this.rate,required this.imageUrl,required this.amenities});final String id,roomType,imageUrl;final int capacity,availableRooms;final double rate;final List<String> amenities;factory HotelRoom.fromJson(Map<String,dynamic>j)=>HotelRoom(id:'${j['id']}',roomType:'${j['roomType']??''}',capacity:(j['capacity']as num?)?.toInt()??1,availableRooms:(j['availableRooms']as num?)?.toInt()??0,rate:(j['rate']as num?)?.toDouble()??0,imageUrl:'${j['imageUrl']??''}',amenities:(j['amenities']as List? ?? const[]).map((e)=>'$e').toList());}
class HotelDetails {const HotelDetails({required this.hotel,required this.rooms,required this.description,required this.amenities});final HotelSummary hotel;final List<HotelRoom> rooms;final String description;final List<String> amenities;}
